export { a, falsch, mitnehmen, type RohBlock, type Roh } from './artikel-roh';
const istPaar = (b: RohBlock): b is Paar => 'de' in b;
const text = (sp: Sprache, x: string | Paar) => (typeof x === 'string' ? x : paarText(sp, x));
/** Ein Block in der Sprache `sp`. */
/** Beschriftungen der zwei Didaktik-Bausteine (neutral, ohne Anrede). */
const BAUSTEIN = { falschKopf: P('Stimmt nicht - so ist es', 'Not true - this is how it is'), nein: P('Stimmt nicht', 'Not true'), ja: P('So ist es', 'This is how it is'), mitnehmen: P('Zum Mitnehmen', 'Take away') };
const waehleBlock = (sp: Sprache, b: RohBlock): Block =>
  istPaar(b) ? paarText(sp, b)
  : 'h' in b ? { h: paarText(sp, b.h) }
  : 'ul' in b ? { ul: b.ul.map(x => paarText(sp, x)) }
  : 'ol' in b ? { ol: b.ol.map(x => paarText(sp, x)) }
  : 'code' in b ? { code: text(sp, b.code) }
  : 'apa' in b ? { apa: text(sp, b.apa) }
  : 'falsch' in b ? { falsch: { kopf: paarText(sp, BAUSTEIN.falschKopf), nein: paarText(sp, BAUSTEIN.nein), mythos: paarText(sp, b.falsch.mythos), ja: paarText(sp, BAUSTEIN.ja), richtig: paarText(sp, b.falsch.richtig) } }
  : 'mitnehmen' in b ? { mitnehmen: { kopf: paarText(sp, BAUSTEIN.mitnehmen), punkte: b.mitnehmen.map(x => paarText(sp, x)) } }
  : { tabelle: { kopf: b.tabelle.kopf.map(x => paarText(sp, x)), zeilen: b.tabelle.zeilen.map(z => z.map(x => text(sp, x))) } };

/**
 * Welche Abschnitte der Hilfe offen stehen (30.10.2026): der erste, „Kurz“/„Wann“, „So geht es (in Statable)“; bei einem Artikel zu einer Auswertung (`frage-*`)
 * auch „Ergebnis lesen“, „Alpha lesen“ und „Was oft falsch verstanden wird“. Alle anderen Zwischenüberschriften klappt die Hilfe ein.
 * Erkannt an der deutschen Überschrift (gilt für jede Sprache); zurück kommt der Text der Überschrift in der gewählten Sprache.
 */
const OFFEN = /^(Kurz|Wann|So geht es( in Statable)?)$/, OFFEN_FRAGE = /^(Ergebnis lesen|Alpha lesen|Was oft falsch verstanden wird)$/;
const offeneUeberschriften = (sp: Sprache, id: string, bl: RohBlock[]): string[] =>
  bl.flatMap((b, i) => (!istPaar(b) && 'h' in b && (i === 0 || id === 'ueber-statable' || OFFEN.test(b.h.de) || id.startsWith('frage-') && OFFEN_FRAGE.test(b.h.de)) ? [paarText(sp, b.h)] : []));
/** Die offenen Zwischenüberschriften eines Artikels (leer, wenn es ihn nicht gibt). */
export const artikelOffen = (id: string, sprache: Sprache): string[] => { const r = ROH.find(x => x.id === id); return r ? offeneUeberschriften(sprache, r.id, r.inhalt) : []; };
/** Gliederung eines Artikels für „Lernen“ (Usability Stufe 6): die Zwischenüberschriften „Kurz“/„Wann“ und „So geht es (in Statable)“ in der Sprache `sprache`, erkannt an der deutschen Überschrift. */
export const artikelGliederung = (id: string, sprache: Sprache): { kurz: string[]; statable: string[] } => {
  const r = ROH.find(x => x.id === id), hh = r ? r.inhalt.filter((b): b is { h: Paar } => !istPaar(b) && 'h' in b) : [];
  return { kurz: hh.filter(b => /^(Kurz|Wann)$/.test(b.h.de)).map(b => paarText(sprache, b.h)), statable: hh.filter(b => /^So geht es( in Statable)?$/.test(b.h.de)).map(b => paarText(sprache, b.h)) };
};

/** Rangtests: wann exakt, wann genähert; Nullen; Niveau des Intervalls (Fachblatt G9). Steht in den Artikeln zum Gruppenvergleich und zur Vorher-nachher-Frage. */
const RANG_EXAKT = P('Exakt oder genähert: Bei weniger als 50 Werten je Gruppe (Wilcoxon: weniger als 50 Paare mit Unterschied) rechnet Statable den p-Wert exakt, auch bei gleichen Werten (bedingte Verteilung); darüber gilt die Normalnäherung. Beim Wilcoxon-Test entfallen Paare ohne Unterschied vor dem Ranken (wie in SPSS). R rechnet im exakten Test anders: Es rankt Paare ohne Unterschied mit (Pratt-Verfahren). Darum können Werte von R abweichen. Mit kleinen Fallzahlen lässt sich ein Niveau von genau 95 % nicht erreichen; Statable nennt dann das erreichte Niveau.', 'Exact or approximate: with fewer than 50 values per group (Wilcoxon: fewer than 50 pairs with a difference) Statable computes the p value exactly, also with tied values (conditional distribution); above that the normal approximation applies. In Wilcoxon, pairs without a difference are dropped before ranking (as in SPSS). R computes the exact test differently: it ranks pairs without a difference along (Pratt method). So values can differ from R. With small sample sizes a level of exactly 95% cannot be reached; Statable then states the level reached.');

